using System.Net;
using System.Text;
using Kachalka;
static class GameCatalogTests
{
    sealed class Handler(Func<HttpRequestMessage,CancellationToken,Task<HttpResponseMessage>> action):HttpMessageHandler
    {protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct)=>action(request,ct);}
    static byte[] Bytes(string text)=>Encoding.UTF8.GetBytes(text);
    public static async Task Run(string root)
    {
        void Check(bool value,string label){if(!value)throw new Exception(label);Console.WriteLine("PASS: "+label);}
        var page=GameCatalog.ParsePage(Bytes("""
            {"items":[{"name":"Portal 2","logo":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/620/abc/capsule_sm_120.jpg"},{"id":400,"name":"Portal","platforms":{"windows":true},"tiny_image":"https://cdn.akamai.steamstatic.com/steam/apps/400/header.jpg"},{"id":12,"name":"Mac only","platforms":{"windows":false}},{"name":"Invalid","logo":"https://other.test/apps/123/file.jpg"}]}
            """));
        Check(page.Items.Select(x=>x.OnlineId).SequenceEqual(["steam:620","steam:400"]),"Steam compact and search rows retain app identity and reject non-Windows or foreign image identities");
        Check(GameCatalog.Query(new GameBrowse("",GameBrowse.Popular,"",2)).Query.Contains("start=40")&&GameCatalog.Query(new GameBrowse("",GameBrowse.Popular,"",2)).Query.Contains("os=win")&&GameCatalog.Query(new GameBrowse("Portal & 2")).AbsoluteUri.Contains("api/storesearch/")&&GameCatalog.Query(new GameBrowse("Portal & 2")).Query.Contains("Portal%20%26%202"),"Windows game pagination and escaped title search use their verified Steam endpoints");
        Check(GameCatalog.TryId(page.Items[0].PageUrl,out var id)&&id==620&&!GameCatalog.TryId("https://store.steampowered.com.evil.test/app/620/",out _)&&!GameCatalog.TryId("https://store.steampowered.com/app/620/?x=1",out _),"game card and download identities accept only canonical Steam pages");
        var raw=Bytes("""
            {"620":{"success":true,"data":{"type":"game","name":"Portal 2","platforms":{"windows":true},"short_description":"<b>Головоломка</b><script>bad()</script>","header_image":"https://cdn.akamai.steamstatic.com/steam/apps/620/header.jpg","release_date":{"date":"18 апр. 2011 г."},"genres":[{"id":"25","description":"Приключения"}],"pc_requirements":{"minimum":"<strong>ОС:</strong> Windows<br>2 GB"},"developers":["Valve"],"publishers":["Valve"]}}}
            """);
        Check(GameBrowse.Sorts.All(sort=>GameCatalog.Query(new GameBrowse("",sort)).Query.Contains("untags=113"))&&!GameCatalog.Query(new GameBrowse("Portal")).Query.Contains("untags"),"every browsing list leaves out Free to Play games while a title search still finds any game by name");
        Check(GameCatalog.HeroImage(page.Items[0])=="https://cdn.akamai.steamstatic.com/steam/apps/620/library_hero.jpg"&&GameCatalog.HeroImage(new MediaItem(1,"x","Игры","",0,"","","#000000"){PageUrl="https://example.test/app/620/"})==null,"the banner's wide picture is Steam's library hero of that exact app");
        // Real Steam answers, recorded on 12 October 2026 and trimmed: a discounted game, a poorly reviewed one, a free one, a game not out yet, a pre-order, a game without a date and a bundle.
        var today=new DateTime(2026,10,12);
        var sample=GameCatalog.ParsePage(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","steam-search-sample.json")),today);
        var rdr=sample.Items.Single(x=>x.OnlineId=="steam:1174180");var madden=sample.Items.Single(x=>x.OnlineId=="steam:3940610");var zoo=sample.Items.Single(x=>x.OnlineId=="steam:3219030");var fable=sample.Items.Single(x=>x.OnlineId=="steam:2769570");var deadlock=sample.Items.Single(x=>x.OnlineId=="steam:1422450");
        Check(sample.Items.Length==5&&sample.Items.All(x=>x.OnlineId!="steam:730")&&sample.HasNext,"a free game and a bundle never enter the catalogue, however Steam tags them");
        Check(rdr.Store is {Price:"$14.99",OriginalPrice:"$59.99",Discount:75,Free:false,ReviewPercent:93,ReviewTone:"positive"}&&rdr.Store.ReviewCount>10_000&&rdr.Store.ReviewLabel.Length>0&&rdr.Store.HasPrice&&rdr.Store.HasDiscount&&rdr.Store.DiscountText=="−75%"&&!rdr.Store.Soon,"a discounted game keeps its price, the old price, the discount and Steam's review verdict");
        Check(madden.Store is {Discount:35,ReviewPercent:37,ReviewTone:"negative"}&&madden.Store.ReviewText=="👍 37%","a poorly reviewed game keeps its negative tone and share");
        Check(rdr.ImageUrl!.Contains("/apps/1174180/header.jpg?t=")&&madden.ImageUrl!.Contains("/20bc1dc9ca6f0c349c7a7d6f59afd2ff3320d883/capsule_231x87.jpg")&&zoo.ImageUrl!.EndsWith("capsule_231x87.jpg?t=1791804561"),"a game with plain artwork gets the sharper header, and a game with hashed artwork keeps the capsule that always exists");
        Check(rdr.Year==2019&&rdr.Genre=="Приключенческие игры, Экшены"&&rdr.CardMeta=="2019 · Приключенческие игры","the year and genre come from the search row, so a card names them before any details load");
        Check(zoo.Store is {Soon:true,HasPrice:true,ReviewPercent:0}&&!zoo.Store.HasReview&&zoo.Year==2026&&zoo.CardMeta=="13 окт. 2026"&&fable.Store is {Soon:true}&&fable.CardMeta=="23 фев. 2027","a game that is not out yet is marked as coming and shows its date instead of a year");
        Check(deadlock.Store is {Soon:true,HasPrice:false,HasDiscount:false}&&deadlock.CardMeta=="Дата не объявлена"&&deadlock.Store!.SoonTip.Contains("не объявлена"),"a game without a date or a price still lists, as coming soon");
        Check(GameRelease.Parse("24 фев. 2022 г.",today)==(2022,false)&&GameRelease.Parse("20 мая. 2025 г.",today)==(2025,false)&&GameRelease.Parse("13 окт. 2026 г.",today)==(2026,true)&&GameRelease.Parse("12 окт. 2026 г.",today)==(2026,false)&&GameRelease.Parse("2027",today)==(2027,true)&&GameRelease.Parse("Ещё не объявлена",today)==(0,true)&&GameRelease.Parse("",today)==(0,false),"release dates are read the way Steam's Russian store writes them");
        Check(GameCatalog.Query(new GameBrowse("",GameBrowse.Specials)).Query.Contains("specials=1")&&GameCatalog.Query(new GameBrowse("",GameBrowse.New)).Query.Contains("filter=popularnew")&&GameCatalog.Query(new GameBrowse("",GameBrowse.Soon)).Query.Contains("filter=popularwishlist")&&GameCatalog.Query(new GameBrowse("",GameBrowse.Popular,"rpg")).Query.Contains("&tags=122")&&!GameCatalog.Query(new GameBrowse("",GameBrowse.Popular,"")).Query.Contains("&tags="),"each list asks Steam for its own sort and genre");
        Check(GameGenres.All.Select(x=>x.Key).Distinct().Count()==GameGenres.All.Length&&GameGenres.All.Select(x=>x.Tag).Distinct().Count()==GameGenres.All.Length&&GameShelves.Home.Where(x=>x.Genre.Length>0).All(x=>GameGenres.ByKey(x.Genre)!=null)&&GameShelves.Home.Select(x=>x.Key).Distinct().Count()==GameShelves.Home.Length,"the genre chips and the home shelves refer to distinct, known genres");
        Check(new GameBrowse("",GameBrowse.Specials,"coop").Title=="Кооператив · Игры со скидкой"&&new GameBrowse("Portal").Title=="Результаты поиска"&&new GameBrowse("",GameBrowse.Soon).Title=="Скоро выйдут","a list is titled by its sort and genre");
        var found=GameCatalog.ParsePage(Bytes("""{"total":2,"items":[{"type":"app","name":"ELDEN RING","id":1245620,"price":{"currency":"USD","initial":5999,"final":3999},"tiny_image":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1245620/capsule_231x87.jpg","platforms":{"windows":true}},{"type":"app","name":"Free Thing","id":9,"tiny_image":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/9/capsule_231x87.jpg","platforms":{"windows":true}}]}"""));
        Check(found.Items[0].Store is {Price:"$39.99",OriginalPrice:"$59.99",Discount:33}&&found.Items[1].Store==null&&!found.HasNext,"a title search carries prices too, and a game with no price stays plain");
        Check(GamePrice.Format("USD",5999)=="$59.99"&&GamePrice.Format("USD",1000)=="$10"&&GamePrice.Format("RUB",44500)=="445 руб."&&GamePrice.Format("EUR",1999)=="19,99€"&&GamePrice.Format("PLN",2500)=="25 PLN"&&GamePrice.Format("USD",0)=="","prices in cents are written the way the stores write them");
        Check(GameNumbers.Count(2_739_409)=="2,7 млн"&&GameNumbers.Count(31_416)=="31 тыс."&&GameNumbers.Count(549)=="549"&&GameNumbers.Count(1234)=="1\u00A0234"&&GameNumbers.Digits("2,739,409 ")==2_739_409,"review counts are shortened the way people read them");
        var portal=GameCatalog.ParseDetail(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","steam-appdetails-portal2.json")),page.Items[0]);
        Check(portal.Gallery.Length==12&&portal.Gallery.All(x=>x.Thumb.Contains(".600x338.")&&x.Full.Contains(".1920x1080.")&&x.Thumb.StartsWith("https://shared.akamai.steamstatic.com/")),"the store page carries up to twelve screenshots with a thumbnail and a full-size address each");
        Check(portal.Russian==GameRussian.Voiced&&portal.Traits.Contains("Для одного игрока")&&portal.Traits.Contains("Кооператив")&&portal.Traits.Contains("Полная поддержка контроллеров")&&portal.Price=="$9.99"&&portal.Discount==0&&portal.Metacritic==95&&portal.ReleaseDate=="18 апр. 2011 г."&&!portal.ComingSoon,"the store page tells the Russian language, the game modes, the price, the score and the release date");
        string Languages(string text)=>"""{"620":{"success":true,"data":{"type":"game","name":"X","platforms":{"windows":true},"supported_languages":""" + System.Text.Json.JsonSerializer.Serialize(text) + "}}}";
        Check(GameCatalog.ParseDetail(Bytes(Languages("английский, русский, немецкий")),page.Items[0]).Russian==GameRussian.Interface&&GameCatalog.ParseDetail(Bytes(Languages("английский<strong>*</strong>, немецкий")),page.Items[0]).Russian==GameRussian.Absent&&GameCatalog.ParseDetail(Bytes(Languages("")),page.Items[0]).Russian==GameRussian.Unknown,"Russian is told apart as voiced, text only, missing and unknown");
        string Discounted(int percent)=>"""{"620":{"success":true,"data":{"type":"game","name":"X","platforms":{"windows":true},"price_overview":{"currency":"USD","initial":5999,"final":1499,"discount_percent":""" + percent + ""","initial_formatted":"$59.99","final_formatted":"$14.99"}}}}""";
        var sale=GameCatalog.ParseDetail(Bytes(Discounted(75)),page.Items[0]);
        Check(sale.Price=="$14.99"&&sale.OriginalPrice=="$59.99"&&sale.Discount==75&&GameCatalog.ParseDetail(Bytes(Discounted(0)),page.Items[0]).OriginalPrice=="","a discounted game keeps its old price and the percentage, and a full-price one has none");
        var verdict=GameCatalog.ParseReview(Bytes("""{"success":1,"query_summary":{"num_reviews":0,"review_score":9,"review_score_desc":"Overwhelmingly Positive","total_positive":94743,"total_negative":1458,"total_reviews":96201},"reviews":[],"cursor":"*"}"""));
        Check(verdict is {Percent:98,Count:96201,Score:9,Tone:"positive",Label:"Крайне положительные"}&&GameCatalog.ParseReview(Bytes("""{"query_summary":{"review_score":5,"total_positive":3,"total_negative":4}}"""))==null&&GameCatalog.ParseReview(Bytes("""{"query_summary":{"review_score":5,"total_positive":50,"total_negative":50}}""")) is {Tone:"mixed"}&&GameCatalog.ParseReview(Bytes("""{"query_summary":{"review_score":3,"total_positive":10,"total_negative":50}}""")) is {Tone:"negative"},"Steam's review summary becomes a share, a count and a verdict, and a game with under ten reviews has none");
        var detail=GameCatalog.ParseDetail(raw,page.Items[0]);
        Check(detail.Item.Year==2011&&detail.Item.Description=="Головоломка"&&detail.Requirements.Contains("\n")&&detail.Developers=="Valve", "Steam details preserve localized release year and requirements without executable HTML");
        var priced=GameCatalog.ParseDetail(Bytes(Encoding.UTF8.GetString(raw).Replace("\"developers\"","\"price_overview\":{\"final_formatted\":\"399 руб.\"},\"metacritic\":{\"score\":95},\"developers\"")),page.Items[0]);
        var free=GameCatalog.ParseDetail(Bytes(Encoding.UTF8.GetString(raw).Replace("\"developers\"","\"is_free\":true,\"metacritic\":{\"score\":0},\"developers\"")),page.Items[0]);
        Check(priced.Price=="399 руб."&&priced.Metacritic==95&&detail.Price==""&&detail.Metacritic==0&&free.Price=="Бесплатно"&&free.Metacritic==0,"store details carry the price and the Metacritic score, and ignore a missing or empty score");
        var rejected=false;try{GameCatalog.ParseDetail(Bytes(Encoding.UTF8.GetString(raw).Replace("\"game\"","\"dlc\"")),page.Items[0]);}catch(InvalidDataException){rejected=true;}
        Check(rejected,"a DLC response cannot be treated as the requested base Windows game");
        SourceEntry Row(string title)=>new("fixture",title,"Fixture","","magnet:?xt=urn:btih:"+new string('a',40),null);
        Check(GameReleaseSources.Matches(detail.Item,Row("Portal 2 (2011) PC RePack"))&&!GameReleaseSources.Matches(detail.Item,Row("Portal 3 (2026) PC"))&&!GameReleaseSources.Matches(GameCatalog.Item(400,"Portal"),Row("Portal Knights (2017) PC")),"game release matching rejects numbered sequels and another title sharing a prefix");
        Check(!GameReleaseSources.Matches(detail.Item,Row("Portal 2 (2011) Xbox360"))&&!GameReleaseSources.Matches(detail.Item,Row("Portal 2 Update v1.0 PC")),"console and update-only packages stay out of Windows game offers");
        Check(GameReleaseSources.Matches(detail.Item,Row("Portal 2 [v. 2.0.0.1 build 6180] (2011) PC | RePack от Tolyak26"))&&GameReleaseSources.Matches(detail.Item,Row("Portal 2 v. 2.0.0.1 PC"))&&GameReleaseSources.Matches(detail.Item,Row("Portal 2 (2011) РС | RePack от NSIS")),"real version brackets, spaced versions and Cyrillic PC labels are accepted");
        Check(GameReleaseSources.Matches(detail.Item,Row("[PC] Portal 2 [L] [RUS + ENG] (2011)"))&&GameReleaseSources.Matches(detail.Item,Row("[CD] Portal 2 [P] (2011)")),"existing platform and disc metadata prefixes remain valid");
        Check(!GameReleaseSources.Matches(detail.Item,Row("Portal 2 [DLC] PC"))&&!GameReleaseSources.Matches(detail.Item,Row("Portal 2 (2011) Update v1.0 PC"))&&!GameReleaseSources.Matches(detail.Item,Row("Portal 2 - Любительские карты (2011) PC")),"standalone DLC, dated updates and custom maps are not offered as the base game");
        var elden=GameCatalog.Item(1245620,"ELDEN RING");
        Check(GameReleaseSources.Matches(elden,Row("[DL] Elden Ring [P] [RUS + ENG + 12 / ENG] (2022, RPG) (1.16.1 + 6 DLC) [Scene]"))&&!GameReleaseSources.Matches(elden,Row("Elden Ring Nightreign: Deluxe Edition (2025) PC"))&&!GameReleaseSources.Matches(elden,Row("[PS4] Elden Ring (2022)")),"RuTracker metadata tags keep the exact game while related titles and console packages remain excluded");
        Check(GameReleaseSources.Queries(GameCatalog.Item(1086940,"Baldur’s Gate 3™")).SequenceEqual(["Baldur's Gate 3"]),"Steam typography is cleaned for queries without changing the displayed title");
        var rutorGames=File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","rutor-games-portal2.html"));
        var gameRows=GameReleaseSources.ParseRutor(rutorGames,detail.Item);
        Check(gameRows.Count>=3&&gameRows.Any(x=>x.Title.Contains("РС"))&&gameRows.Any(x=>x.Title.Contains("[v."))&&gameRows.All(x=>ReleaseQuality.Downloadable(x)&&GameReleaseSources.WindowsRelease(x.Title)),"the observed RuTor game table produces real downloadable Windows rows");
        var knabenGames=KnabenSource.Parse(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","knaben-games-elden.json")),elden);
        Check(knabenGames.Any(x=>x.Source=="RuTracker")&&knabenGames.All(x=>(x.Source is "RuTracker" or "The Pirate Bay")&&x.Via=="Knaben"&&ReleaseQuality.Downloadable(x)&&GameReleaseSources.WindowsRelease(x.Title)),"observed Knaben PC/Games results survive parsing and keep valid hashes");
        var portalIndex=KnabenSource.Parse(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","knaben-games-portal2.json")),detail.Item);
        Check(portalIndex.Count>0&&portalIndex.All(x=>x.Source=="The Pirate Bay"&&ReleaseQuality.Downloadable(x))&&portalIndex.Any(x=>x.Title.Contains("DODI")),"the game index retains PC repacks while rejecting book, audio and unrelated results");
        using(var gameSearchClient=new SourceClient(new Handler((request,ct)=>{
            Check(request.RequestUri!.AbsoluteUri.Contains("/search/0/8/000/2/Portal%202")&&!request.RequestUri.AbsoluteUri.Contains("%E2%84%A2"),"the RuTor source searches the clean Steam title in the games category");
            return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new ByteArrayContent(rutorGames)});
        })))
        {
            var provider=GameReleaseSources.Create(gameSearchClient,GameCatalog.Item(620,"Portal 2™"),[]).First();
            var result=await ReleaseSearch.RunAsync([provider],timeout:TimeSpan.FromSeconds(2));
            Check(result.Items.Length==gameRows.Count&&result.Sources.Single().State==SourceState.Ready,"the actual game provider publishes parsed releases through the search coordinator");
        }
        SourceEntry Release(string title,int? seeds=100,long size=5_000_000_000)=>new("id-"+title,title,"Fixture","","magnet:?xt=urn:btih:"+new string('b',40),null,size,seeds);
        Check(GameReleaseInfo.Kind(Release("Portal 2 (2011) PC RePack by xatab [RUS/ENG]"))=="Репак"&&GameReleaseInfo.Group(Release("Portal 2 (2011) PC RePack by xatab [RUS/ENG]"))=="xatab"&&GameReleaseInfo.Russian(Release("Portal 2 (2011) PC RePack by xatab [RUS/ENG]"))&&!GameReleaseInfo.Russian(Release("Portal 2 (2011) PC [ENG]"))&&GameReleaseInfo.Kind(Release("Portal 2 (2011) PC GOG"))=="Лицензия"&&GameReleaseInfo.Kind(Release("Portal 2 (2011) PC"))=="Игра","a release row names its kind, author and language from its own title");
        Check(GameReleaseInfo.Version(Release("Portal 2 v1.2.3 RePack"))=="v1.2.3"&&GameReleaseInfo.Version(Release("Portal 2 Build 12345"))=="Build 12345"&&GameReleaseInfo.Version(Release("Portal 2 (2011)"))==null&&GameReleaseInfo.Group(Release("Portal 2 [FitGirl Repack]"))=="FitGirl"&&GameReleaseInfo.Group(Release("Portal 2 RePack by SomeoneNew"))=="SomeoneNew"&&GameReleaseInfo.WithDlc(Release("Portal 2 + All DLCs")),"versions, repack authors and bundled add-ons are read from the title only");
        var plain=Release("Portal 2 (2011) PC",150);var russian=Release("Portal 2 (2011) PC RePack [RUS]",110);var rare=Release("Portal 2 (2011) PC [RUS]",60);
        Check(GameReleaseRecommendation.Pick([plain,rare,russian])?.Entry==russian&&GameReleaseRecommendation.Pick([plain,rare])?.Entry==plain&&GameReleaseRecommendation.Pick([Release("Portal 2 (2011) PC",5)])==null&&GameReleaseRecommendation.Pick([Release("Portal 2 (2011) PS4",500)])==null,"the recommended release is the best seeded one, a Russian-language release wins among the well seeded, and few seeders recommend nothing");
        Check(GameReleaseRecommendation.Pick([plain,russian])!.Reason.Contains("русский язык")&&GameReleaseRecommendation.Pick([plain])!.Reason.StartsWith("Больше всего отдающих"),"the reason names only facts that are in the release row");
        var card=DownloadMetadata.Card(new DownloadItem{MediaSection="Игры",MediaPageUrl=detail.Item.PageUrl,MediaTitle=detail.Item.Title,MediaYear=2011,ImageUrl=detail.Item.ImageUrl});
        Check(card?.OnlineId=="steam:620"&&card.Title==detail.Item.Title&&card.Year==2011,"queued games reopen the same Steam card with their title and poster");
        var calls=0;using var client=new SourceClient(new Handler((request,ct)=>{calls++;return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new ByteArrayContent(raw)});}));
        await new GameCatalog(client).Detail(page.Items[0],CancellationToken.None);await new GameCatalog(client).Detail(page.Items[0],CancellationToken.None);
        Check(calls==2,"reopening a game reuses its persisted details and review summary rather than downloading them again");
        using var slow=new SourceClient(new Handler(async(_,ct)=>{await Task.Delay(Timeout.Infinite,ct);throw new Exception("Unreachable");}));using var cancel=new CancellationTokenSource(40);var stopped=false;
        try{await new GameCatalog(slow).Browse(new GameBrowse("Cancellation fixture"),cancel.Token);}catch(OperationCanceledException){stopped=true;}
        Check(stopped,"leaving a game catalog cancels an unfinished HTTP request");
    }
}
